"""Native/Python resolver parity on generated bytes; no game files or functions."""

import ctypes
import struct
import subprocess
import tempfile
import unittest
from pathlib import Path

from darkest_dungeon_patches.address_scan import ImageRange, Signature, resolve, signatures
from darkest_dungeon_patches.paths import COMMON_NATIVE


class NativeRange(ctypes.Structure):
    _fields_ = [
        ("bytes", ctypes.c_void_p),
        ("size", ctypes.c_size_t),
        ("address", ctypes.c_size_t),
        ("memory_size", ctypes.c_size_t),
        ("flags", ctypes.c_uint),
    ]


class NativeSignature(ctypes.Structure):
    _fields_ = [
        ("name", ctypes.c_char_p),
        ("pattern", ctypes.c_char_p),
        ("symbol", ctypes.c_uint),
        ("group", ctypes.c_uint),
        ("capture", ctypes.c_uint),
        ("kind", ctypes.c_uint),
        ("adjustment", ctypes.c_int),
        ("target_flags", ctypes.c_uint),
    ]


class AddressScanTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temporary = tempfile.TemporaryDirectory(prefix="dd-scan-unit-")
        root = Path(cls.temporary.name)
        source = root / "scan.c"
        source.write_text("""#include "address_scan.h"
int scan(const DdRange *ranges, size_t count, const DdSignature *feature,
         uintptr_t *result) { return dd_scan(ranges,count,feature,result); }
""")
        library = root / "scan.so"
        subprocess.run(
            [
                "clang",
                "-std=c11",
                "-O2",
                "-Wall",
                "-Wextra",
                "-Werror",
                "-fPIC",
                "-shared",
                "-I",
                str(COMMON_NATIVE),
                str(source),
                "-o",
                str(library),
            ],
            check=True,
        )
        cls.library = ctypes.CDLL(str(library))
        cls.library.scan.argtypes = [
            ctypes.POINTER(NativeRange),
            ctypes.c_size_t,
            ctypes.POINTER(NativeSignature),
            ctypes.POINTER(ctypes.c_size_t),
        ]
        cls.library.scan.restype = ctypes.c_int

    @classmethod
    def tearDownClass(cls):
        cls.temporary.cleanup()

    def native(self, ranges, feature):
        buffers = [ctypes.create_string_buffer(region.data) for region in ranges]
        native_ranges = (NativeRange * len(ranges))(
            *[
                NativeRange(
                    ctypes.addressof(buffer),
                    len(region.data),
                    region.address,
                    region.memory_size,
                    region.flags,
                )
                for region, buffer in zip(ranges, buffers)
            ]
        )
        native = NativeSignature(
            b"fixture",
            feature.pattern.encode(),
            0,
            feature.group,
            feature.capture,
            feature.kind,
            feature.adjustment,
            feature.target_flags,
        )
        output = ctypes.c_size_t(0xFEED)
        status = self.library.scan(
            native_ranges, len(ranges), ctypes.byref(native), ctypes.byref(output)
        )
        return status, output.value

    def test_relative_call_and_data_targets_move_independently(self):
        marker = bytes(range(0x81, 0x91))
        for code, data, target_offset in ((0x4000, 0x1000, 96), (0x97000, 0xF4000, 128)):
            with self.subTest(code=code, data=data):
                for kind in ("call", "data"):
                    target = code + target_offset if kind == "call" else data + 16
                    prefix, capture, flags = (
                        (b"\xe8", 1, 1) if kind == "call" else (b"\x48\x8b\x05", 3, 2)
                    )
                    raw = prefix + struct.pack("<i", target - code - capture - 4) + marker
                    pattern = " ".join(
                        [*[f"{b:02x}" for b in prefix], *["??"] * 4, *[f"{b:02x}" for b in marker]]
                    )
                    feature = Signature("TARGET", pattern, 4, capture, 1, 0, flags)
                    ranges = [
                        ImageRange(code, raw + b"\0" * 160, 256, 5),
                        ImageRange(data, b"\0" * 32, 256, 6),
                    ]
                    self.assertEqual(self.native(ranges, feature), (1, target))
                    self.assertEqual(resolve(ranges, [feature]), ({"TARGET": target}, []))

    def test_absolute_operands_and_context_adjustment(self):
        for width, kind, code, data in ((4, 2, 0x4000, 0x150000), (8, 3, 0x16000, 0x121500000)):
            marker = bytes(range(12))
            raw = marker + int(data).to_bytes(width, "little")
            feature = Signature(
                "DATA",
                " ".join([*[f"{b:02x}" for b in marker], *["??"] * width]),
                4,
                12,
                kind,
                8,
                2,
            )
            ranges = [ImageRange(code, raw, len(raw), 5), ImageRange(data, b"\0" * 32, 32, 6)]
            self.assertEqual(self.native(ranges, feature), (1, data + 8))
            self.assertEqual(resolve(ranges, [feature]), ({"DATA": data + 8}, []))
        feature = Signature("ENTRY", " ".join(f"{b:02x}" for b in marker), 4, 0, 0, -4, 1)
        self.assertEqual(
            self.native([ImageRange(0x100, b"\xff" * 4 + marker, 16, 5)], feature), (1, 0x100)
        )

    def test_missing_ambiguous_and_data_hits_do_not_select_an_address(self):
        marker = bytes(range(16))
        feature = Signature("ENTRY", " ".join(f"{b:02x}" for b in marker), 1, 0, 0, 0, 1)
        for raw, flags, expected in ((marker + marker, 5, 2), (marker, 6, 0), (marker[:-1], 5, 0)):
            ranges = [ImageRange(0x4000, raw, len(raw), flags)]
            self.assertEqual(self.native(ranges, feature), (expected, 0xFEED))
            self.assertTrue(resolve(ranges, [feature])[1])

    def test_invalid_capture_target_and_profile_are_rejected(self):
        marker = bytes(range(16))
        feature = Signature(
            "DATA", " ".join([*[f"{b:02x}" for b in marker], *["??"] * 4]), 4, 16, 1, 0, 2
        )
        ranges = [ImageRange(0x4000, marker + struct.pack("<i", 0x100000), 20, 5)]
        self.assertEqual(self.native(ranges, feature), (-1, 0xFEED))
        self.assertTrue(resolve(ranges, [feature])[1])
        for pattern in ("?? ??", "00 zz", "00 "):
            malformed = Signature("BAD", pattern, 1, 0, 0, 0, 1)
            self.assertEqual(self.native(ranges, malformed), (-1, 0xFEED))

    def test_native_pointer_field_follows_accessor_and_checks_bounds(self):
        marker = bytes(range(0x81, 0x91))
        pattern = " ".join(["e8", *["??"] * 4, *[f"{b:02x}" for b in marker]])
        feature = Signature("ACTOR_SPRITE_FIELD", pattern, 4, 1, 5, 0, 8)
        for offset in (0x1070, 0x10E0):
            caller = b"\xe8" + struct.pack("<i", 0x100 - 5) + marker
            setter = b"\x48\x89\xb7" + struct.pack("<I", offset) + b"\xc3"
            ranges = [ImageRange(0x4000, caller, len(caller), 5), ImageRange(0x4100, setter, 8, 5)]
            self.assertEqual(self.native(ranges, feature), (1, offset))
            self.assertEqual(resolve(ranges, [feature]), ({"ACTOR_SPRITE_FIELD": offset}, []))
            broken = [ranges[0], ImageRange(0x4100, b"\x90" + setter[1:], 8, 5)]
            self.assertEqual(self.native(broken, feature), (-1, 0xFEED))
        direct = Signature(
            "FIELD", " ".join([*[f"{b:02x}" for b in marker], *["??"] * 4]), 4, 16, 4, 0, 8
        )
        for offset in (0, 7, 0x10008):
            self.assertEqual(
                self.native(
                    [ImageRange(0x1000, marker + struct.pack("<I", offset), 20, 5)], direct
                ),
                (-1, 0xFEED),
            )

    def test_shipping_profiles_have_bounded_masked_unique_symbol_definitions(self):
        for platform in ("linux", "windows"):
            features = signatures(platform)
            self.assertEqual(len(features), len({entry.symbol for entry in features}))
            self.assertTrue(
                {"STORAGE", "RESOURCE", "HOOK_NEW", "NATIVE_NEW"}
                <= {entry.symbol for entry in features}
            )
            for entry in features:
                tokens = entry.pattern.split()
                self.assertGreaterEqual(sum(token != "??" for token in tokens), 12)
                self.assertLessEqual(len(tokens), 128)
                if entry.kind:
                    width = 8 if entry.kind == 3 else 4
                    self.assertEqual(tokens[entry.capture : entry.capture + width], ["??"] * width)
